<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Cat FAQ</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f5f7fb;
        --panel: rgba(255, 255, 255, 0.84);
        --panel-border: rgba(15, 23, 42, 0.08);
        --text: #0f172a;
        --muted: #475569;
        --accent: #2563eb;
        --accent-soft: rgba(37, 99, 235, 0.1);
        --shadow: 0 24px 80px rgba(15, 23, 42, 0.12);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, #e0ecff 0%, transparent 40%),
          linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
        min-height: 100vh;
      }

      .page {
        width: min(960px, calc(100% - 32px));
        margin: 0 auto;
        padding: 56px 0 72px;
      }

      .hero {
        padding: 28px 28px 0;
        margin-bottom: 24px;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        padding: 8px 12px;
        border-radius: 999px;
        background: var(--accent-soft);
        color: var(--accent);
        font-size: 0.85rem;
        font-weight: 700;
        letter-spacing: 0.02em;
      }

      h1 {
        margin: 18px 0 10px;
        font-size: clamp(2.4rem, 5vw, 4.2rem);
        line-height: 0.98;
        letter-spacing: -0.05em;
      }

      .intro {
        margin: 0;
        max-width: 60ch;
        color: var(--muted);
        font-size: 1.05rem;
        line-height: 1.7;
      }

      .faq-shell {
        margin-top: 28px;
        padding: 8px;
        border: 1px solid var(--panel-border);
        border-radius: 28px;
        background: var(--panel);
        backdrop-filter: blur(18px);
        box-shadow: var(--shadow);
      }

      .details {
        display: grid;
        gap: 14px;
      }

      .example {
        overflow: hidden;
        border: 1px solid rgba(148, 163, 184, 0.24);
        border-radius: 20px;
        background: rgba(255, 255, 255, 0.92);
        transition: transform 160ms ease, box-shadow 160ms ease, border-color 160ms ease;
      }

      .example:hover {
        transform: translateY(-1px);
        box-shadow: 0 12px 30px rgba(15, 23, 42, 0.08);
        border-color: rgba(37, 99, 235, 0.24);
      }

      .question {
        width: 100%;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        padding: 22px 22px;
        border: 0;
        background: transparent;
        color: var(--text);
        font: inherit;
        text-align: left;
        cursor: pointer;
      }

      .question strong {
        font-size: 1.02rem;
        line-height: 1.4;
      }

      .chevron {
        flex: 0 0 auto;
        width: 40px;
        height: 40px;
        border-radius: 999px;
        display: grid;
        place-items: center;
        background: #f1f5f9;
        color: var(--accent);
        transition: transform 180ms ease, background 180ms ease;
      }

      .example[aria-expanded="true"] .chevron {
        transform: rotate(180deg);
        background: var(--accent-soft);
      }

      .answer {
        padding: 0 22px 22px;
        color: var(--muted);
        line-height: 1.75;
      }

      .answer p {
        margin: 0;
      }

      .answer ul {
        margin: 12px 0 0;
        padding-left: 20px;
      }

      .answer li + li {
        margin-top: 8px;
      }

      .footer-note {
        margin-top: 18px;
        padding: 0 28px;
        color: #64748b;
        font-size: 0.92rem;
      }

      @media (max-width: 640px) {
        .page {
          width: min(100% - 20px, 960px);
          padding: 20px 0 40px;
        }

        .hero,
        .footer-note {
          padding-left: 14px;
          padding-right: 14px;
        }

        .faq-shell {
          border-radius: 22px;
        }

        .question,
        .answer {
          padding-left: 18px;
          padding-right: 18px;
        }
      }
    </style>
  </head>
  <body>
    <main class="page">
      <section class="hero" aria-labelledby="faq-title">
        <span class="eyebrow">Cats 101</span>
        <h1 id="faq-title">Frequently asked questions about cats</h1>
        <p class="intro">
          A quick guide to the mysterious, cozy, and occasionally chaotic creatures
          we share our homes with.
        </p>
      </section>

      <section class="faq-shell" aria-label="Cat frequently asked questions">
        <div id="faq-root"></div>
      </section>

      <p class="footer-note">Click any question to reveal the answer.</p>
    </main>

    <script>
      const faqs = [
        {
          question: "Why do cats purr?",
          answer:
            "Cats purr for comfort, communication, and sometimes self-soothing. A purr often means contentment, but it can also show up when a cat is nervous, healing, or asking for attention.",
        },
        {
          question: "How much sleep do cats need?",
          answer:
            "Most cats sleep 12 to 16 hours a day, and some even more. Their energy comes in bursts, so a long nap schedule is perfectly normal.",
        },
        {
          question: "Why do cats knead with their paws?",
          answer:
            "Kneading is a comforting habit that usually starts in kittenhood. Adult cats keep doing it when they feel relaxed, safe, or especially attached to a person or place.",
        },
        {
          question: "Do cats need to go outside?",
          answer:
            "No. Indoor cats can live full, healthy lives when they have enrichment, play, climbing spaces, and regular veterinary care. A safe indoor setup is often the best option.",
        },
        {
          question: "What makes a cat happy?",
          answer:
            "Predictable routines, interactive play, fresh water, clean litter boxes, cozy resting spots, and respectful handling all help cats feel secure and satisfied.",
        },
      ];

      function AccordionItem({ question, answer, open = false, index }) {
        return `
          <div class="example" data-index="${index}" aria-expanded="${open}">
            <button class="question" type="button" aria-expanded="${open}" aria-controls="answer-${index}" id="question-${index}">
              <strong>${question}</strong>
              <span class="chevron" aria-hidden="true">⌄</span>
            </button>
            <div class="details answer" id="answer-${index}" role="region" aria-labelledby="question-${index}" hidden="${open ? "" : "true"}">
              <p>${answer}</p>
            </div>
          </div>
        `;
      }

      function FAQPage({ items }) {
        return `
          <div class="details">
            ${items.map((item, index) => AccordionItem({ ...item, index })).join("")}
          </div>
        `;
      }

      document.getElementById("faq-root").innerHTML = FAQPage({ items: faqs });

      document.querySelectorAll(".example").forEach((item) => {
        const button = item.querySelector(".question");
        const panel = item.querySelector(".answer");

        button.addEventListener("click", () => {
          const expanded = button.getAttribute("aria-expanded") === "true";
          button.setAttribute("aria-expanded", String(!expanded));
          item.setAttribute("aria-expanded", String(!expanded));
          panel.hidden = expanded;
        });
      });
    </script>
  </body>
</html>
